select case when amount >= 1630 then 'high' when amount >= 760 then 'mid' else 'low' end as amount_bucket, count(*) as payment_count, round(avg(amount), 2) as avg_amount from payments where not (hour(paid_at) between 10 and 17 and (status in ('SUCCESS', 'REFUNDED') or to_date(paid_at) < '2023-04-24')) group by case when amount >= 1630 then 'high' when amount >= 760 then 'mid' else 'low' end
